import java.awt.GraphicsEnvironment;
import javax.swing.*;
public class Main {
  public static void main(String[] args) throws Exception {
    System.setProperty("java.awt.headless", "true");      // CodeShare has no screen
    System.setProperty("awt.toolkit", "sun.awt.HToolkit"); // build controls without one
    SwingUtilities.invokeAndWait(new Runnable() {
      public void run() {
        TerminalPanel panel = new TerminalPanel();
        System.out.println("Built on the EDT: " + SwingUtilities.isEventDispatchThread());
        System.out.println("Controls on the panel: " + panel.getComponentCount());
        for (int i = 0; i < panel.getComponentCount(); i++) {
          JLabel label = (JLabel) panel.getComponent(i);
          System.out.println("Label " + (i + 1) + ": " + label.getText());
        }
      }
    });
    if (GraphicsEnvironment.isHeadless()) {
      System.out.println("No screen: the window stays closed.");
      return;
    }
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        JFrame frame = new JFrame("Vehicle Terminal");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setContentPane(new TerminalPanel());
        frame.setSize(720, 180);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
      }
    });
  }
}

