public class TerminalPanel extends JPanel {
  private JLabel plate = new JLabel();
  private JLabel route = new JLabel();
  public TerminalPanel(Jeepney jeep) {
    add(plate);
    add(route);
    showVehicle(jeep);
  }
  public void showVehicle(Jeepney jeep) {
    plate.setText(jeep.getPlateNumber() + " | " + jeep.getDriverName());
    route.setText(jeep.getRoute());
  }
  public String getPlateText() { return plate.getText(); }
  public String getRouteText() { return route.getText(); }
}

