import java.awt.event.*;
import javax.swing.*;
public class TerminalPanel extends JPanel implements ActionListener {
  private JTextField plate = new JTextField("NXA 123", 8);
  private JLabel result = new JLabel("Waiting for a click");
  public TerminalPanel() {
    JLabel label = new JLabel("Plate:");
    label.setLabelFor(plate);
    JButton show = new JButton("Show");
    show.addActionListener(this);
    add(label);
    add(plate);
    add(show);
    add(result);
  }
  @Override public void actionPerformed(ActionEvent e) {
    result.setText("Plate: " + plate.getText().trim());
  }
}

import javax.swing.*;
public class Main {
  public static void main(String[] args) throws Exception {
    System.setProperty("java.awt.headless", "true");      // CodeShare has no screen
    System.setProperty("awt.toolkit", "sun.awt.HToolkit"); // build controls without one
    SwingUtilities.invokeAndWait(new Runnable() {
      public void run() {
        TerminalPanel panel = new TerminalPanel();
        JTextField plate = (JTextField) panel.getComponent(1);
