import java.util.concurrent.CountDownLatch;
import javax.swing.*;
public class ReadyWorker extends SwingWorker<String, Void> {
  private JLabel status;
  private JButton button;
  private CountDownLatch finished;
  public ReadyWorker(JLabel status, JButton button, CountDownLatch finished) {
    this.status = status;
    this.button = button;
    this.finished = finished;
  }
  @Override protected String doInBackground() throws Exception {
    Thread.sleep(1000);                  // the slow job runs on a worker thread
    return "Ready: NXA 123";
  }
  @Override protected void done() {      // Swing runs done() on the EDT
    try {
      status.setText(get());
    } catch (Exception e) {
      status.setText("Check failed; try again.");
    }
    button.setEnabled(true);
    finished.countDown();
  }
}

