public abstract class Vehicle {
    private String plateNumber;
    private String driverName;
    private int passengers;

    public Vehicle(String plateNumber, String driverName) {
        this.plateNumber = plateNumber;
        this.driverName = driverName;
        this.passengers = 0;
    }

    public String getPlateNumber() { return plateNumber; }
    public String getDriverName()  { return driverName; }
    public int getPassengers()     { return passengers; }

    // WEDNESDAY: the setter now THROWS instead of only printing
    public void setPassengers(int passengers) {
        if (passengers < 0) {
            throw new IllegalArgumentException("Passengers cannot be negative: " + passengers);
        }
        this.passengers = passengers;
    }

    // THURSDAY: user-defined checked exception
    public void board(int count) throws OverloadException {
        if (passengers + count > getCapacity()) {
            throw new OverloadException(plateNumber + " is full! Capacity "
                + getCapacity() + ", but " + (passengers + count) + " tried to ride.");
        }
        passengers = passengers + count;
    }

    // THURSDAY: user-defined unchecked exception
    public double quoteFare(double km) {
        if (km <= 0) {
            throw new InvalidDistanceException("Distance must be more than 0 km, got " + km);
        }
        return computeFare(km);
    }

    public abstract double computeFare(double km);
    public abstract int getCapacity();

    public void showInfo() {
        System.out.println(plateNumber + " | Driver: " + driverName
            + " | Passengers: " + passengers + "/" + getCapacity());
    }
}

public class VehicleNotFoundException extends Exception {
    public VehicleNotFoundException(String message) {
        super(message);
    }
}

import java.util.Locale;
public class FareService {
  public static String quote(
      String plate, String distance)
      throws VehicleNotFoundException {
    double km =
      Double.parseDouble(distance.trim());
    if (!Double.isFinite(km) || km <= 0) {
      throw new InvalidDistanceException(
        "Use a finite km above 0.");
    }
    Vehicle[] fleet = {
      new Jeepney("NXA 123", "Mang Ramon",
        "Monumento-Divisoria"),
      new Tricycle("TRC 456", "Kuya Ben",
        "Bagong Silang TODA"),
      new Bus("BUS 789", "Aling Rosa", 50),
      new Jeepney("NYB 321", "Mang Tonyo",
        "Sangandaan-Recto")
    };
    String key = plate.trim()
      .toUpperCase(Locale.ROOT);
    for (Vehicle v : fleet) {
      if (v.getPlateNumber().equals(key)) {
        double fare = v.quoteFare(km);
        if (!Double.isFinite(fare)) {
          throw new InvalidDistanceException(
            "Distance is too large.");
        }
        return String.format(Locale.ROOT,
          "%s: P%.2f", key, fare);
      }
    }
    throw new VehicleNotFoundException(
      "Unknown plate: " + key);
  }
}

public class FareCheck {
  public static void main(String[] args) {
    String[][] cases = {{"NXA 123", "5"}, {"TRC 456", "2"},
      {"BUS 789", "4"}, {"NYB 321", "6"}, {"nxA 123", " 5 "},
      {"ZZZ", "5"}, {"NXA 123", "abc"}, {"NXA 123", "0"},
      {"NXA 123", "NaN"}, {"NXA 123", "1e309"}};
    for (String[] c : cases) {
      try {
        System.out.println(
          FareService.quote(c[0], c[1]));
      } catch (VehicleNotFoundException |
        NumberFormatException | InvalidDistanceException e) {
        System.out.println(
          e.getClass().getSimpleName() + ": "
          + e.getMessage());
      }
    }
  }
}

import javax.swing.*;
public class ReadyTask implements Runnable {
  private JLabel status;
  private JButton button;
  public ReadyTask(
      JLabel status, JButton button) {
    this.status = status;
    this.button = button;
  }
  @Override public void run() {
    String message;
    try {
      Thread.sleep(1000);
      message = "Ready: NXA 123";
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      message = "Check interrupted; try again.";
    }
    final String outcome = message;
    SwingUtilities.invokeLater(new Runnable() {
      public void run() {
        status.setText(outcome);
        button.setEnabled(true);
      }
    });
  }
}

import java.util.concurrent.CountDownLatch;
import javax.swing.*;
public class ReadyWorker extends SwingWorker<String, Void> {
  private JLabel status;
  private JButton button;
  private CountDownLatch finished;
  public ReadyWorker(JLabel status, JButton button, CountDownLatch finished) {
    this.status = status;
    this.button = button;
    this.finished = finished;
  }
  @Override protected String doInBackground() throws Exception {
    Thread.sleep(1000);                  // the slow job runs on a worker thread
    return "Ready: NXA 123";
  }
  @Override protected void done() {      // Swing runs done() on the EDT
    try {
      status.setText(get());
    } catch (Exception e) {
      status.setText("Check failed; try again.");
    }
    button.setEnabled(true);
    finished.countDown();
  }
}

public class ThemeCheck {
  static class StoreItem {
    private int price;
    StoreItem(int price) { this.price = price; }
    int total(String text) {
      int qty = Integer.parseInt(text.trim());
      if (qty < 1 || qty > 1000) {
        throw new IllegalArgumentException(
          "Use quantity 1 to 1000.");
      }
      return price * qty;
    }
  }
  public static void main(String[] args) {
    StoreItem rice = new StoreItem(55);
    for (String s : new String[]{"2","0","abc"}) {
      try {
        System.out.println("P" + rice.total(s));
      }
      catch (IllegalArgumentException e) {
        System.out.println(e.getMessage());
      }
    }
  }
}

